	private static void invokeRetireIdleSnapshot(SailSource source) throws Exception {
		Method retire;
		try {
			retire = SailSource.class.getMethod("retireIdleSnapshot");
		} catch (NoSuchMethodException e) {
			throw new AssertionError("growth drain must expose root-cache retirement", e);
		}
		try {
			retire.invoke(source);
		} catch (InvocationTargetException e) {
			Throwable cause = e.getCause();
			if (cause instanceof Exception exception) {
				throw exception;
			}
			if (cause instanceof Error error) {
				throw error;
			}
			throw new AssertionError(cause);
		}
	}

	@Test
	void readersAfterFlushUseNewSnapshotGeneration() throws SailException {
		PinnedBackingSource backing = new PinnedBackingSource();
		SailSourceBranch branch = new SailSourceBranch(backing, new DynamicModelFactory(), false);
		IRI subject = SimpleValueFactory.getInstance().createIRI("urn:s");
		IRI predicate = SimpleValueFactory.getInstance().createIRI("urn:p");
		IRI object = SimpleValueFactory.getInstance().createIRI("urn:o");

		SailDataset before = branch.dataset(IsolationLevels.SNAPSHOT);
		assertFalse(hasStatement(before, subject, predicate, object));

		SailSink sink = branch.sink(IsolationLevels.SNAPSHOT);
		sink.approve(subject, predicate, object, null);
		sink.flush();
		sink.close();
		branch.flush();

		SailDataset after = branch.dataset(IsolationLevels.SNAPSHOT);
		try {
			assertEquals(2, backing.datasetCount.get(), "a flush retires the old snapshot generation");
			assertTrue(hasStatement(after, subject, predicate, object),
					"a later reader must see changes published by the branch flush");
		} finally {
			before.close();
			after.close();
			branch.close();
		}
	}

	@Test
	void externallyStaleSnapshotIsRetiredForRefreshableReaders() throws SailException {
		AtomicBoolean oldSnapshotCurrent = new AtomicBoolean(true);
		AtomicInteger oldCloseCount = new AtomicInteger();
		AtomicInteger replacementCloseCount = new AtomicInteger();
		TrackingBackingSource backing = new TrackingBackingSource(index -> index == 0
				? new SnapshotTrackingDataset(oldCloseCount, oldSnapshotCurrent::get)
				: new CloseCountingDataset(replacementCloseCount));
		SailSourceBranch branch = new SailSourceBranch(backing, new DynamicModelFactory(), true);

		SailDataset oldReader = branch.dataset(IsolationLevels.SNAPSHOT);
		oldSnapshotCurrent.set(false);
		SailDataset replacementReader = branch.dataset(IsolationLevels.READ_COMMITTED);

		assertEquals(2, backing.datasetCount.get(), "new readers must not borrow a stale generation");
		assertTrue(new CloseCountingDataset(new AtomicInteger()).isSnapshotCurrent());
		assertFalse(new DelegatingSailDataset(
				new SnapshotTrackingDataset(new AtomicInteger(), () -> false)) {
		}.isSnapshotCurrent(), "delegating datasets must forward the generation-currentness signal");

		oldReader.close();
		assertEquals(1, oldCloseCount.get());
		assertEquals(0, replacementCloseCount.get());
		branch.close();
		assertEquals(0, replacementCloseCount.get());
		replacementReader.close();
		assertEquals(1, replacementCloseCount.get());
	}

	@Test
	void nestedChangesetDatasetsDelegateSnapshotCurrentness() throws SailException {
		AtomicInteger closeCount = new AtomicInteger();
		TrackingBackingSource backing = new TrackingBackingSource(
				ignored -> new SnapshotTrackingDataset(closeCount, () -> false));
		SailSourceBranch branch = new SailSourceBranch(backing, new DynamicModelFactory(), false);
		IRI predicate = SimpleValueFactory.getInstance().createIRI("urn:p");
		IRI object = SimpleValueFactory.getInstance().createIRI("urn:o");
		SailSink firstChange = branch.sink(IsolationLevels.NONE);
		firstChange.approve(SimpleValueFactory.getInstance().createIRI("urn:first"), predicate, object, null);
		SailSink secondChange = branch.sink(IsolationLevels.NONE);
		secondChange.approve(SimpleValueFactory.getInstance().createIRI("urn:second"), predicate, object, null);

		try (branch; firstChange; secondChange) {
			firstChange.flush();
			try (SailDataset firstObserver = branch.dataset(IsolationLevels.SNAPSHOT)) {
				secondChange.flush();
				try (SailDataset observer = branch.dataset(IsolationLevels.SNAPSHOT)) {
					assertFalse(observer.isSnapshotCurrent(),
							"currentness must pass through every nested Changeset dataset wrapper");
				}
			}
		}
		assertEquals(1, closeCount.get());
	}

	@Test
	void readCommittedAdmissionWaitsOutsideBranchLockForPublication() throws Exception {
		PublicationLockBackingSource backing = new PublicationLockBackingSource();
		SailSourceBranch branch = new SailSourceBranch(backing, new DynamicModelFactory(), false);

		try (branch; ExecutorService executor = Executors.newFixedThreadPool(2)) {
			SailClosable publication = backing.beginPublication();
			Future<SailDataset> read = executor.submit(() -> branch.dataset(IsolationLevels.READ_COMMITTED));
			try {
				assertTrue(backing.readerWaitingForPublication.await(5, TimeUnit.SECONDS),
						"the reader must reach the publication gate before opening a branch dataset");
				Future<Boolean> branchLockProbe = executor.submit(branch::isChanged);
				assertFalse(branchLockProbe.get(1, TimeUnit.SECONDS),
						"a reader waiting for publication must not retain the branch semaphore");
				backing.publishExternalChange();
			} finally {
				publication.close();
			}
			try (SailDataset observer = read.get(5, TimeUnit.SECONDS)) {
				assertEquals(1, backing.datasetCount.get(),
						"the reader must open its dataset only after the competing publication completes");
				assertTrue(observer.isSnapshotCurrent(), "the returned dataset must reflect the competing commit");
			}
		}
	}

	@Test
	void interruptedRefreshableAdmissionStopsAfterClosingRetryScope() throws SailException {
		InterruptingRetryBackingSource backing = new InterruptingRetryBackingSource();
		SailSourceBranch branch = new SailSourceBranch(backing, new DynamicModelFactory(), false);
		SailDataset returned = null;
		SailException failure = null;
		try {
			try {
				returned = branch.dataset(IsolationLevels.READ_COMMITTED);
			} catch (SailException expected) {
				failure = expected;
			}

			boolean interruptPreserved = Thread.interrupted();
			if (returned != null) {
				returned.close();
				returned = null;
			}

			assertTrue(interruptPreserved, "an interrupted retry must preserve the thread's interrupt flag");
			assertTrue(failure != null, "an interrupted retry must fail with SailException");
			assertEquals(1, backing.datasetCount.get(), "the retry must stop before acquiring another candidate");
			assertEquals(backing.admissionScopesOpened.get(), backing.admissionScopesClosed.get(),
					"the acquisition scope must close before interruption is propagated");
			assertTrue(backing.admissionScopeClosedWithInterrupt.get(),
					"the retry scope must close while the interrupt is still preserved");
		} finally {
			Thread.interrupted();
			if (returned != null) {
				returned.close();
			}
			branch.close();
		}
	}

