	@Test
	void autoFlushSkipsBusyWriterWithoutHoldingInferredBranchSemaphore() throws Exception {
		WriterLeaseBackingSource backing = new WriterLeaseBackingSource();
		SailSourceBranch explicitBranch = new SailSourceBranch(backing, new DynamicModelFactory(), false);
		SailSourceBranch inferredBranch = new SailSourceBranch(backing, new DynamicModelFactory(), true);
		try (explicitBranch;
				inferredBranch;
				SailDataset inferredObserver = inferredBranch.dataset(IsolationLevels.NONE)) {
			SailSink inferredChanges = inferredBranch.sink(IsolationLevels.NONE);
			inferredChanges.approve(SimpleValueFactory.getInstance().createIRI("urn:s"),
					SimpleValueFactory.getInstance().createIRI("urn:p"),
					SimpleValueFactory.getInstance().createIRI("urn:o"), null);
			inferredChanges.flush();
			inferredChanges.close();

			CountDownLatch explicitFlushComplete = new CountDownLatch(1);
			CountDownLatch allowExplicitBranchProbe = new CountDownLatch(1);
			CountDownLatch explicitBranchProbeComplete = new CountDownLatch(1);
			Future<?> explicitWriter = null;
			Future<?> inferredAutoFlush = null;
			boolean futuresCompleted = false;

			try (ExecutorService executor = Executors.newFixedThreadPool(2)) {
				try {
					explicitWriter = executor.submit(() -> {
						try (SailDataset explicitObserver = explicitBranch.dataset(IsolationLevels.SERIALIZABLE)) {
							SailSink explicitChanges = explicitBranch.sink(IsolationLevels.SERIALIZABLE);
							explicitChanges.approve(SimpleValueFactory.getInstance().createIRI("urn:explicit-s"),
									SimpleValueFactory.getInstance().createIRI("urn:explicit-p"),
									SimpleValueFactory.getInstance().createIRI("urn:explicit-o"), null);
							explicitChanges.flush();
							explicitChanges.close();
							explicitBranch.flush();
						}
						explicitFlushComplete.countDown();
						AdmissionCloseBackingSource.await(allowExplicitBranchProbe,
								"permission for the explicit branch semaphore probe");
						inferredBranch.isChanged();
						explicitBranchProbeComplete.countDown();
						explicitBranch.close();
					});

					assertTrue(explicitFlushComplete.await(5, TimeUnit.SECONDS),
							"the explicit root should finish its flush while retaining the writer lease");
					assertTrue(backing.writerReferences.get() > 0,
							"the explicit serializable sink should retain its writer lease after flush");
					inferredAutoFlush = executor.submit(inferredObserver::close);
					assertTrue(backing.writerTryStarted.await(5, TimeUnit.SECONDS),
							"the inferred auto-flush should observe that the writer lease is busy");
					inferredAutoFlush.get(5, TimeUnit.SECONDS);

					allowExplicitBranchProbe.countDown();
					assertTrue(explicitBranchProbeComplete.await(5, TimeUnit.SECONDS),
							"the explicit root must acquire the inferred branch semaphore while auto-flush skips the busy writer");
					explicitWriter.get(5, TimeUnit.SECONDS);
					inferredBranch.flush();
					futuresCompleted = true;
				} finally {
					allowExplicitBranchProbe.countDown();
					if (!futuresCompleted) {
						// Unblock both futures after preserving the lock-order failure as the test result.
						backing.forceReleaseWriter();
					}
				}
			}

			assertEquals(0, backing.writerReferences.get(),
					"both publication scopes and the explicit sink must release the lease");
		}
	}

