	@Test
	void unionPublicationDoesNotExposePrimaryBeforeAdditionalFlush() throws Exception {
		PublicationOrderCoordinator coordinator = new PublicationOrderCoordinator();
		PublicationOrderBackingSource primaryBacking = new PublicationOrderBackingSource(coordinator, true);
		PublicationOrderBackingSource additionalBacking = new PublicationOrderBackingSource(coordinator, false);
		SailSourceBranch primary = new SailSourceBranch(primaryBacking, new DynamicModelFactory(), false);
		SailSourceBranch additional = new SailSourceBranch(additionalBacking, new DynamicModelFactory(), false);
		UnionSailSource union = new UnionSailSource(primary, additional);

		try (union; ExecutorService executor = Executors.newFixedThreadPool(2)) {
			for (SailSourceBranch branch : List.of(primary, additional)) {
				try (SailSink sink = branch.sink(IsolationLevels.SERIALIZABLE)) {
					sink.approve(SimpleValueFactory.getInstance().createIRI("urn:s"),
							SimpleValueFactory.getInstance().createIRI("urn:p"),
							SimpleValueFactory.getInstance().createIRI("urn:o"), null);
					sink.flush();
				}
			}
			union.prepare();

			Future<?> preparedCommit = executor.submit(() -> {
				coordinator.commitThread.set(Thread.currentThread());
				union.flush();
			});
			Future<?> competingCommit = null;
			try {
				assertTrue(coordinator.primaryFlushStarted.await(5, TimeUnit.SECONDS),
						"the primary root should pause before completing its flush");
				competingCommit = executor.submit(() -> {
					coordinator.competingThread.set(Thread.currentThread());
					try (SailClosable publication = primaryBacking.beginPublication()) {
						coordinator.competingCommitCompleted.countDown();
					}
				});
				assertTrue(coordinator.competingPublicationStarted.await(5, TimeUnit.SECONDS),
						"the competing commit should queue between the two root flushes");
				coordinator.allowPrimaryFlush.countDown();
				preparedCommit.get(5, TimeUnit.SECONDS);
				competingCommit.get(5, TimeUnit.SECONDS);
				assertTrue(coordinator.additionalFlushCompleted.getCount() == 0,
						"the additional root must finish before the competing commit proceeds");
				assertFalse(coordinator.competingCommitSawPartialPublication.get(),
						"a competing commit must not interleave between explicit and inferred publication");
			} finally {
				coordinator.allowPrimaryFlush.countDown();
				if (competingCommit != null && !competingCommit.isDone()) {
					competingCommit.cancel(true);
				}
			}
		}
	}

