	private void preparedChangesetReservationLetsCommitFinishBeforeCompetitorTakesBranchSemaphore(boolean writes,
			boolean nested)
			throws Exception {
		WriterLeaseBackingSource backing = new WriterLeaseBackingSource();
		SailSourceBranch parent = nested ? new SailSourceBranch(backing, new DynamicModelFactory(), false) : null;
		SailSourceBranch branch = new SailSourceBranch(nested ? parent : backing, new DynamicModelFactory(), false);
		CountDownLatch prepared = new CountDownLatch(1);
		CountDownLatch allowCommit = new CountDownLatch(1);
		CountDownLatch competingWriterAcquired = new CountDownLatch(1);
		CountDownLatch competingBranchLockAcquired = new CountDownLatch(1);
		CountDownLatch commitFlushComplete = new CountDownLatch(1);

		try (parent; branch; ExecutorService executor = Executors.newFixedThreadPool(2)) {
			Future<?> preparedCommit = executor.submit(() -> {
				SailSink sink = branch.sink(writes ? IsolationLevels.SNAPSHOT : IsolationLevels.SERIALIZABLE);
				if (writes) {
					sink.approve(SimpleValueFactory.getInstance().createIRI("urn:s"),
							SimpleValueFactory.getInstance().createIRI("urn:p"),
							SimpleValueFactory.getInstance().createIRI("urn:o"), null);
				} else {
					sink.observe(null, null, null, new Resource[0]);
				}
				sink.prepare();
				sink.flush();
				prepared.countDown();
				AdmissionCloseBackingSource.await(allowCommit, "prepared branch commit");
				branch.flush();
				sink.close();
				commitFlushComplete.countDown();
			});

			Future<?> competingPublisher = null;
			boolean completed = false;
			try {
				assertTrue(prepared.await(5, TimeUnit.SECONDS), "the changeset should complete its prepare phase");
				competingPublisher = executor.submit(() -> {
					try (SailClosable publication = backing.beginPublication()) {
						assertEquals(0, backing.preparedOwnerReleased.getCount(),
								"a competing writer must wait for the prepared owner reservation to release");
						competingWriterAcquired.countDown();
						branch.isChanged();
						competingBranchLockAcquired.countDown();
					}
				});
				assertTrue(backing.writerWaitStarted.await(5, TimeUnit.SECONDS),
						"the competing publisher waits outside the branch semaphore for the prepared owner");
				allowCommit.countDown();
				assertTrue(commitFlushComplete.await(5, TimeUnit.SECONDS));
				assertTrue(competingWriterAcquired.await(5, TimeUnit.SECONDS));
				assertTrue(competingBranchLockAcquired.await(5, TimeUnit.SECONDS),
						"the competing publisher acquires the branch semaphore after the prepared sink releases it");
				preparedCommit.get(5, TimeUnit.SECONDS);
				competingPublisher.get(5, TimeUnit.SECONDS);
				completed = true;
			} finally {
				allowCommit.countDown();
				if (!completed) {
					backing.forceReleaseWriter();
					try {
						preparedCommit.get(5, TimeUnit.SECONDS);
					} catch (ExecutionException | TimeoutException expected) {
						// Preserve the assertion that identified the lock-order failure.
					}
					if (competingPublisher != null) {
						try {
							competingPublisher.get(5, TimeUnit.SECONDS);
						} catch (ExecutionException | TimeoutException expected) {
							// Preserve the assertion that identified the lock-order failure.
						}
					}
				}
			}
		}
	}

	@Test
	void closingBranchDuringSnapshotAdmissionDoesNotReopenIt() throws Exception {
		CloseDuringAdmissionBackingSource backing = new CloseDuringAdmissionBackingSource();
		SailSourceBranch branch = new SailSourceBranch(backing, new DynamicModelFactory(), false);

		try (branch; ExecutorService executor = Executors.newSingleThreadExecutor()) {
			Future<SailDataset> inFlight = executor.submit(() -> branch.dataset(IsolationLevels.SNAPSHOT));
			try {
				assertTrue(backing.admissionStarted.await(5, TimeUnit.SECONDS));
				branch.close();
				backing.allowAdmissionReturn.countDown();

				ExecutionException failure = assertThrows(ExecutionException.class,
						() -> inFlight.get(5, TimeUnit.SECONDS),
						"an admission that returns after close must not install a new generation");
				assertTrue(failure.getCause() instanceof SailException);
				assertEquals("SailSourceBranch is closed", failure.getCause().getMessage());
				assertEquals(1, backing.datasetCount.get());
				assertEquals(1, backing.admittedDatasetCloseCount.get());
				assertThrows(SailException.class, () -> branch.dataset(IsolationLevels.SNAPSHOT));
			} finally {
				backing.allowAdmissionReturn.countDown();
				try {
					inFlight.get(5, TimeUnit.SECONDS).close();
				} catch (ExecutionException expected) {
					// The failed admission has already closed its private backing dataset.
				}
			}
		}
	}

	private static final class TrackingBackingSource extends BackingSailSource {
		private final AtomicInteger datasetCount = new AtomicInteger();
		private final IntFunction<SailDataset> datasets;

		private TrackingBackingSource(IntFunction<SailDataset> datasets) {
			this.datasets = datasets;
		}

		@Override
		public SailSink sink(IsolationLevel level) {
			return new NoopSailSink();
		}

		@Override
		public SailDataset dataset(IsolationLevel level) {
			return datasets.apply(datasetCount.getAndIncrement());
		}
	}

	private static final class PublicationCountingBackingSource extends BackingSailSource {
		private final AtomicInteger approvals = new AtomicInteger();
		private final AtomicInteger observations = new AtomicInteger();
		private final AtomicInteger flushes = new AtomicInteger();
		private final AtomicInteger datasetCount = new AtomicInteger();
		private final AtomicInteger datasetCloseCount = new AtomicInteger();

		@Override
		public SailSink sink(IsolationLevel level) {
			return new NoopSailSink() {
				@Override
				public void approve(Resource subj, IRI pred, Value obj, Resource ctx) {
					approvals.incrementAndGet();
				}

				@Override
				public void observe(Resource subj, IRI pred, Value obj, Resource... contexts) {
					observations.incrementAndGet();
				}

				@Override
				public void flush() {
					flushes.incrementAndGet();
				}
			};
		}

		@Override
		public SailDataset dataset(IsolationLevel level) {
			datasetCount.incrementAndGet();
			return new CloseCountingDataset(datasetCloseCount);
		}
	}

	private static final class InterruptingRetryBackingSource extends BackingSailSource {
		private final AtomicInteger datasetCount = new AtomicInteger();
		private final AtomicInteger datasetCloseCount = new AtomicInteger();
		private final AtomicInteger admissionScopesOpened = new AtomicInteger();
		private final AtomicInteger admissionScopesClosed = new AtomicInteger();
		private final AtomicBoolean admissionScopeClosedWithInterrupt = new AtomicBoolean();

		@Override
		public SailSink sink(IsolationLevel level) {
			return new NoopSailSink();
		}

		@Override
		public SailDataset dataset(IsolationLevel level) {
			int candidate = datasetCount.getAndIncrement();
			return new SnapshotTrackingDataset(datasetCloseCount, () -> {
				if (candidate == 0) {
					Thread.currentThread().interrupt();
					return false;
				}
				return true;
			});
		}

		@Override
		public SailClosable beginDatasetAcquisition(IsolationLevel level) {
			admissionScopesOpened.incrementAndGet();
			return () -> {
				admissionScopesClosed.incrementAndGet();
				admissionScopeClosedWithInterrupt.set(Thread.currentThread().isInterrupted());
			};
		}
	}

	private static final class PublicationLockBackingSource extends BackingSailSource {
		private final AtomicInteger datasetCount = new AtomicInteger();
		private final AtomicInteger committedGeneration = new AtomicInteger();
		private final ReentrantLock publicationLock = new ReentrantLock(true);
		private final AtomicReference<Thread> publicationOwner = new AtomicReference<>();
		private final CountDownLatch readerWaitingForPublication = new CountDownLatch(1);

		@Override
		public SailSink sink(IsolationLevel level) {
			return new NoopSailSink();
		}

		@Override
		public SailDataset dataset(IsolationLevel level) throws SailException {
			int generation = committedGeneration.get();
			datasetCount.incrementAndGet();
			return new VersionedSnapshotDataset(new AtomicInteger(), generation, committedGeneration);
		}

		@Override
		public SailClosable beginPublication() throws SailException {
			if (publicationLock.isLocked() && publicationOwner.get() != Thread.currentThread()) {
				readerWaitingForPublication.countDown();
			}
			boolean outermost = !publicationLock.isHeldByCurrentThread();
			publicationLock.lock();
			if (outermost) {
				publicationOwner.set(Thread.currentThread());
			}
			AtomicBoolean closed = new AtomicBoolean();
			return () -> {
				if (closed.compareAndSet(false, true)) {
					if (publicationLock.getHoldCount() == 1) {
						publicationOwner.set(null);
					}
					publicationLock.unlock();
				}
			};
		}

		private void publishExternalChange() {
			committedGeneration.incrementAndGet();
		}
	}

	private static final class VersionedSnapshotDataset extends CloseCountingDataset {
		private final int generation;
		private final AtomicInteger currentGeneration;

		private VersionedSnapshotDataset(AtomicInteger closeCount, int generation, AtomicInteger currentGeneration) {
			super(closeCount);
			this.generation = generation;
			this.currentGeneration = currentGeneration;
		}

		@Override
		public boolean isSnapshotCurrent() {
			return isCurrent();
		}

		private boolean isCurrent() {
			return generation == currentGeneration.get();
		}
	}

	private static final class BlockingAdmissionBackingSource extends BackingSailSource {
		private final AtomicInteger datasetCount = new AtomicInteger();
		private final AtomicBoolean oldSnapshotCurrent = new AtomicBoolean(true);
		private final AtomicInteger oldSnapshotCloseCount = new AtomicInteger();
		private final CountDownLatch snapshotAdmissionStarted = new CountDownLatch(1);
		private final CountDownLatch capacityAvailable = new CountDownLatch(1);
		private final CountDownLatch nonSnapshotAdmissionStarted = new CountDownLatch(1);

		@Override
		public SailSink sink(IsolationLevel level) {
			return new NoopSailSink();
		}

		@Override
		public SailDataset dataset(IsolationLevel level) throws SailException {
			int admission = datasetCount.getAndIncrement();
			if (admission == 0) {
				return new SnapshotTrackingDataset(oldSnapshotCloseCount, oldSnapshotCurrent::get);
			}
			if (level.isCompatibleWith(IsolationLevels.SNAPSHOT)) {
				snapshotAdmissionStarted.countDown();
				try {
					capacityAvailable.await();
				} catch (InterruptedException e) {
					Thread.currentThread().interrupt();
					throw new SailException("Interrupted while waiting for snapshot capacity", e);
				}
			} else {
				nonSnapshotAdmissionStarted.countDown();
			}
			return new CloseCountingDataset(new AtomicInteger());
		}
	}

	private static final class AdmissionCloseBackingSource extends BackingSailSource {
		private final AtomicInteger datasetCount = new AtomicInteger();
		private final AtomicInteger unusedDatasetCloseCount = new AtomicInteger();
		private final AtomicInteger retiredSnapshotCloseCount = new AtomicInteger();
		private final AtomicInteger nextGenerationCloseCount = new AtomicInteger();
		private final CountDownLatch lowIsolationAdmissionStarted = new CountDownLatch(1);
		private final CountDownLatch allowLowIsolationAdmission = new CountDownLatch(1);
		private final CountDownLatch unusedDatasetCloseStarted = new CountDownLatch(1);
		private final CountDownLatch allowUnusedDatasetClose = new CountDownLatch(1);

		@Override
		public SailSink sink(IsolationLevel level) {
			return new NoopSailSink();
		}

		@Override
		public SailDataset dataset(IsolationLevel level) throws SailException {
			int admission = datasetCount.getAndIncrement();
			if (admission == 0) {
				lowIsolationAdmissionStarted.countDown();
				await(allowLowIsolationAdmission, "low-isolation dataset admission");
				return new CloseCountingDataset(unusedDatasetCloseCount) {
					@Override
					public void close() throws SailException {
						super.close();
						unusedDatasetCloseStarted.countDown();
						await(allowUnusedDatasetClose, "unused low-isolation dataset close");
						throw new SailException("unused admission close");
					}
				};
			}
			if (admission == 1) {
				return new CloseCountingDataset(retiredSnapshotCloseCount, new SailException("snapshot close"));
			}
			return new CloseCountingDataset(nextGenerationCloseCount);
		}

		private static void await(CountDownLatch latch, String action) throws SailException {
			try {
				latch.await();
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new SailException("Interrupted while waiting for " + action, e);
			}
		}
	}

	private static final class BranchLockProbeBackingSource extends BackingSailSource {
		private final AtomicReference<SailSourceBranch> branch = new AtomicReference<>();
		private final AtomicInteger datasetAcquisitionScopes = new AtomicInteger();
		private final AtomicInteger datasetAcquisitionScopesClosed = new AtomicInteger();
		private final AtomicInteger publicationScopes = new AtomicInteger();
		private final AtomicInteger publicationScopesClosed = new AtomicInteger();
		private final AtomicInteger tryPublicationScopes = new AtomicInteger();
		private final AtomicInteger tryPublicationScopesClosed = new AtomicInteger();
		private ExecutorService executor;

		@Override
		public SailSink sink(IsolationLevel level) {
			return new NoopSailSink();
		}

		@Override
		public SailDataset dataset(IsolationLevel level) {
			return new CloseCountingDataset(new AtomicInteger());
		}

		@Override
		public SailClosable beginDatasetAcquisition(IsolationLevel level) throws SailException {
			assertBranchSemaphoreAvailable("dataset admission");
			datasetAcquisitionScopes.incrementAndGet();
			return datasetAcquisitionScopesClosed::incrementAndGet;
		}

		@Override
		public SailClosable beginPublication() throws SailException {
			assertBranchSemaphoreAvailable("publication");
			publicationScopes.incrementAndGet();
			return publicationScopesClosed::incrementAndGet;
		}

		@Override
		public SailClosable tryBeginPublication() throws SailException {
			assertBranchSemaphoreAvailable("nonblocking publication");
			tryPublicationScopes.incrementAndGet();
			return tryPublicationScopesClosed::incrementAndGet;
		}

		private void assertBranchSemaphoreAvailable(String scope) throws SailException {
			try {
				executor.submit(() -> branch.get().isChanged()).get(5, TimeUnit.SECONDS);
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new SailException("Interrupted while checking branch lock during " + scope, e);
			} catch (ExecutionException | TimeoutException e) {
				throw new SailException("Branch semaphore was held while opening " + scope, e);
			}
		}
	}

	private static final class ScopeTrackingBackingSource extends BackingSailSource {
		private final AtomicInteger datasetAdmissionScopes = new AtomicInteger();
		private final AtomicInteger datasetAdmissionScopesClosed = new AtomicInteger();
		private final AtomicInteger publicationScopes = new AtomicInteger();
		private final AtomicInteger publicationScopesClosed = new AtomicInteger();
		private final AtomicInteger currentnessChecks = new AtomicInteger();

		@Override
		public SailSink sink(IsolationLevel level) {
			return new NoopSailSink();
		}

		@Override
		public SailDataset dataset(IsolationLevel level) {
			return new CloseCountingDataset(new AtomicInteger());
		}

		@Override
		public SailClosable beginDatasetAcquisition(IsolationLevel level) {
			datasetAdmissionScopes.incrementAndGet();
			return datasetAdmissionScopesClosed::incrementAndGet;
		}

		@Override
		public SailClosable beginPublication() {
			publicationScopes.incrementAndGet();
			return publicationScopesClosed::incrementAndGet;
		}

		@Override
		public boolean isSnapshotCurrent(SailDataset dataset) {
			currentnessChecks.incrementAndGet();
			return false;
		}
	}

	private static final class WriterLeaseBackingSource extends BackingSailSource {
		private final Object writerMonitor = new Object();
		private final AtomicInteger writerReferences = new AtomicInteger();
		private final CountDownLatch writerWaitStarted = new CountDownLatch(1);
		private final CountDownLatch writerTryStarted = new CountDownLatch(1);
		private final CountDownLatch preparedOwnerReleased = new CountDownLatch(1);
		private final AtomicReference<Thread> preparedOwner = new AtomicReference<>();
		private Thread writerOwner;

		@Override
		public SailSink sink(IsolationLevel level) {
			return new NoopSailSink() {
				private SailClosable writerLease;

				@Override
				public void flush() throws SailException {
					if (writerLease == null) {
						writerLease = acquireWriter();
					}
				}

				@Override
				public void close() throws SailException {
					if (writerLease != null) {
						writerLease.close();
						writerLease = null;
					}
				}
			};
		}

		@Override
		public SailDataset dataset(IsolationLevel level) {
			return new CloseCountingDataset(new AtomicInteger());
		}

		@Override
		public SailClosable beginPublication() throws SailException {
			return acquireWriter();
		}

		@Override
		public SailClosable tryBeginPublication() {
			Thread owner = Thread.currentThread();
			synchronized (writerMonitor) {
				if (writerOwner != null && writerOwner != owner) {
					writerTryStarted.countDown();
					return null;
				}
				writerOwner = owner;
				writerReferences.incrementAndGet();
			}
			return writerLease(owner);
		}

		@Override
		public SailClosable beginPreparedWrite() throws SailException {
			preparedOwner.set(Thread.currentThread());
			return acquireWriter();
		}

		private SailClosable acquireWriter() throws SailException {
			Thread owner = Thread.currentThread();
			synchronized (writerMonitor) {
				if (writerOwner != null && writerOwner != owner) {
					writerWaitStarted.countDown();
				}
				while (writerOwner != null && writerOwner != owner) {
					try {
						writerMonitor.wait();
					} catch (InterruptedException e) {
						Thread.currentThread().interrupt();
						throw new SailException("Interrupted while waiting for the backing writer lease", e);
					}
				}
				writerOwner = owner;
				writerReferences.incrementAndGet();
			}

			return writerLease(owner);
		}

		private SailClosable writerLease(Thread owner) {
			AtomicBoolean closed = new AtomicBoolean();
			return () -> {
				if (!closed.compareAndSet(false, true)) {
					return;
				}
				synchronized (writerMonitor) {
					if (writerOwner == owner && writerReferences.decrementAndGet() == 0) {
						if (preparedOwner.get() == owner) {
							preparedOwnerReleased.countDown();
						}
						writerOwner = null;
						writerMonitor.notifyAll();
					}
				}
			};
		}

		private void forceReleaseWriter() {
			synchronized (writerMonitor) {
				writerOwner = null;
				writerReferences.set(0);
				writerMonitor.notifyAll();
			}
		}
	}

	private static final class PreparedWriteTrackingBackingSource extends BackingSailSource {
		private final AtomicReference<SailSourceBranch> branch = new AtomicReference<>();
		private final AtomicInteger acquisitions = new AtomicInteger();
		private final AtomicInteger releases = new AtomicInteger();
		private final AtomicInteger activeReservations = new AtomicInteger();
		private ExecutorService executor;
		private SailException publicationFailure;

		@Override
		public SailSink sink(IsolationLevel level) {
			return new NoopSailSink();
		}

		@Override
		public SailDataset dataset(IsolationLevel level) {
			return new CloseCountingDataset(new AtomicInteger());
		}

		@Override
		public SailClosable beginPublication() {
			if (publicationFailure != null) {
				throw publicationFailure;
			}
			return () -> {
			};
		}

		@Override
		public SailClosable beginPreparedWrite() throws SailException {
			try {
				executor.submit(() -> branch.get().isChanged()).get(5, TimeUnit.SECONDS);
			} catch (InterruptedException e) {
				Thread.currentThread().interrupt();
				throw new SailException("Interrupted while checking branch lock during prepared-write admission", e);
			} catch (ExecutionException | TimeoutException e) {
				throw new SailException("Branch semaphore was held while opening prepared-write admission", e);
			}
			acquisitions.incrementAndGet();
			activeReservations.incrementAndGet();
			AtomicBoolean released = new AtomicBoolean();
			return () -> {
				if (released.compareAndSet(false, true)) {
					activeReservations.decrementAndGet();
					releases.incrementAndGet();
				}
			};
		}
	}

	private static final class PublicationOrderCoordinator {
		private final ReentrantLock publicationLock = new ReentrantLock(true);
		private final AtomicReference<Thread> commitThread = new AtomicReference<>();
		private final AtomicReference<Thread> competingThread = new AtomicReference<>();
		private final CountDownLatch primaryFlushStarted = new CountDownLatch(1);
		private final CountDownLatch allowPrimaryFlush = new CountDownLatch(1);
		private final CountDownLatch additionalFlushCompleted = new CountDownLatch(1);
		private final CountDownLatch competingPublicationStarted = new CountDownLatch(1);
		private final CountDownLatch competingCommitCompleted = new CountDownLatch(1);
		private final AtomicBoolean competingCommitSawPartialPublication = new AtomicBoolean();

		private SailClosable beginPublication() {
			Thread current = Thread.currentThread();
			boolean competing = current == competingThread.get();
			if (competing) {
				competingPublicationStarted.countDown();
			}
			publicationLock.lock();
			if (competing) {
				if (additionalFlushCompleted.getCount() != 0) {
					competingCommitSawPartialPublication.set(true);
				}
				competingCommitCompleted.countDown();
			}
			AtomicBoolean closed = new AtomicBoolean();
			return () -> {
				if (closed.compareAndSet(false, true)) {
					publicationLock.unlock();
				}
			};
		}
	}

	private static final class PublicationOrderBackingSource extends BackingSailSource {
		private final PublicationOrderCoordinator coordinator;
		private final boolean primary;

		private PublicationOrderBackingSource(PublicationOrderCoordinator coordinator, boolean primary) {
			this.coordinator = coordinator;
			this.primary = primary;
		}

		@Override
		public SailSink sink(IsolationLevel level) {
			return new NoopSailSink() {
				@Override
				public void flush() throws SailException {
					if (Thread.currentThread() == coordinator.commitThread.get()) {
						if (primary) {
							coordinator.primaryFlushStarted.countDown();
							AdmissionCloseBackingSource.await(coordinator.allowPrimaryFlush,
									"primary root flush");
						} else {
							coordinator.additionalFlushCompleted.countDown();
						}
					}
				}
			};
		}

		@Override
		public SailDataset dataset(IsolationLevel level) {
			return new CloseCountingDataset(new AtomicInteger());
		}

		@Override
		public SailClosable beginPublication() {
			return coordinator.beginPublication();
		}
	}

	private static final class CloseDuringAdmissionBackingSource extends BackingSailSource {
		private final AtomicInteger datasetCount = new AtomicInteger();
		private final AtomicInteger admittedDatasetCloseCount = new AtomicInteger();
		private final CountDownLatch admissionStarted = new CountDownLatch(1);
		private final CountDownLatch allowAdmissionReturn = new CountDownLatch(1);

		@Override
		public SailSink sink(IsolationLevel level) {
			return new NoopSailSink();
		}

		@Override
		public SailDataset dataset(IsolationLevel level) throws SailException {
			datasetCount.incrementAndGet();
			admissionStarted.countDown();
			AdmissionCloseBackingSource.await(allowAdmissionReturn, "dataset admission after branch close");
			return new CloseCountingDataset(admittedDatasetCloseCount);
		}
	}

	private static boolean hasStatement(SailDataset dataset, Resource subj, IRI pred, Value obj) throws SailException {
		try (CloseableIteration<? extends Statement> statements = dataset.getStatements(subj, pred, obj)) {
			return statements.hasNext();
		}
	}

	private static void awaitLatch(CountDownLatch latch, String action) throws Exception {
		if (!latch.await(5, TimeUnit.SECONDS)) {
			throw new AssertionError("Timed out waiting for " + action);
		}
	}

